import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { needsFullValidation } from '../validation-scope.mjs';

test('only explicitly allowlisted documentation PRs skip code validation', () => {
  for (const paths of [['README.md'], ['CONTRIBUTING.md', 'AGENTS.md'], ['README.md', 'CONTRIBUTING.md', 'AGENTS.md']]) {
    assert.equal(needsFullValidation('pull_request', paths), false);
    for (const event of ['push', 'workflow_dispatch', '', undefined]) {
      assert.equal(needsFullValidation(event, paths), true);
    }
  }
  for (const path of ['src/main.rs', 'frontend/src/app.tsx', 'Cargo.lock', 'LICENSE.md', 'NOTICE.md',
    'CHANGELOG.md', '.github/workflows/validation.yml', '.github/scripts/validation-scope.mjs',
    'frontend/public/assets/licenses/manrope.txt', 'README.md.old', 'readme.md', 'README.md\nsrc/main.rs']) {
    assert.equal(needsFullValidation('pull_request', ['README.md', path]), true, path);
  }
  assert.equal(needsFullValidation('pull_request', []), true);
});

const releasePaths = ['Cargo.toml', 'Cargo.lock', 'CHANGELOG.md'];
const releaseFiles = version => ({
  'Cargo.toml': `[workspace]\nmembers = [".", "crates/core", "desktop"]\n\n[workspace.package]\nversion = "${version}"\n\n[dependencies]\nanyhow = "1"\n`,
  'Cargo.lock': '# Generated by Cargo\nversion = 4\n\n' +
    ['twitch-drops-miner', 'twitch-drops-miner-core', 'twitch-drops-miner-desktop'].map(name =>
      `[[package]]\nname = "${name}"\nversion = "${version}"\ndependencies = ["anyhow"]\n\n`).join('') +
    '[[package]]\nname = "anyhow"\nversion = "1.0.0"\nsource = "registry+https://example.com"\nchecksum = "abc"\n',
  'CHANGELOG.md': `# Changelog\n\n## [v${version}](https://github.com/ohne-b/twitch-drops-miner/releases/tag/v${version}) - 2026-10-12\n\n- a change\n`,
});

test('release PRs skip builds only for matching workspace versions with valid notes', () => {
  const before = releaseFiles('1.0.0');
  const check = (after, paths = releasePaths, event = 'pull_request') => needsFullValidation(event, paths,
    (revision, path) => (revision === 'HEAD^' ? before : after)[path]);
  for (const version of ['1.1.0', '1.1.0-rc.1', '1.1.0+build.1']) {
    const after = releaseFiles(version);
    assert.equal(check(after), false);
    for (const event of ['push', 'workflow_dispatch', '', undefined]) {
      assert.equal(needsFullValidation(event, releasePaths, () => { throw new Error('must not read'); }), true);
    }
    for (const path of ['src/main.rs', 'README.md', '.github/workflows/validation.yml', 'LICENSE.md']) {
      assert.equal(check(after, [...releasePaths, path]), true, path);
    }
    for (const missing of ['Cargo.toml', 'Cargo.lock']) {
      assert.equal(check(after, releasePaths.filter(path => path !== missing)), true);
    }
    for (const [file, from, to] of [
      ['Cargo.toml', 'anyhow = "1"', 'anyhow = "2"'],
      ['Cargo.toml', '"desktop"', '"desktop", "extra"'],
      ['Cargo.lock', 'version = "1.0.0"', 'version = "1.0.1"'],
      ['Cargo.lock', 'checksum = "abc"', 'checksum = "def"'],
      ['Cargo.lock', 'registry+https://example.com', 'registry+https://other.example'],
      ['Cargo.lock', 'dependencies = ["anyhow"]', 'dependencies = []'],
      ['Cargo.lock', `version = "${version}"`, 'version = "0.0.0"'],
      ['Cargo.lock', 'name = "twitch-drops-miner-core"', 'name = "other-core"'],
    ]) {
      assert.equal(check({ ...after, [file]: after[file].replace(from, to) }), true, `${version}: ${from}`);
    }
    assert.equal(check({ ...after, 'Cargo.lock': after['Cargo.lock'] + '\n[[package]]\nname = "extra"\nversion = "1.0.0"\n' }), true);
    for (const notes of ['', before['CHANGELOG.md'], after['CHANGELOG.md'].repeat(2)]) {
      assert.throws(() => check({ ...after, 'CHANGELOG.md': notes }));
    }
  }
  for (const version of ['1.0.0', '0.9.0', 'v1.1.0', '1.1', '01.1.0', '1.1.0;true']) {
    assert.throws(() => check(releaseFiles(version)), version);
  }
  assert.throws(() => needsFullValidation('pull_request', releasePaths, () => { throw new Error('missing blob'); }));
});

test('scope CLI compares the tested merge and cannot hide a code-to-doc rename or missing base', () => {
  const directory = mkdtempSync(join(tmpdir(), 'tdm-scope-'));
  const script = fileURLToPath(new URL('../validation-scope.mjs', import.meta.url));
  const env = { ...process.env, GITHUB_EVENT_NAME: 'pull_request',
    GIT_AUTHOR_NAME: 'Test', GIT_AUTHOR_EMAIL: 'test@example.com',
    GIT_COMMITTER_NAME: 'Test', GIT_COMMITTER_EMAIL: 'test@example.com' };
  const git = (...args) => execFileSync('git', args, { cwd: directory, env, stdio: 'pipe' });
  const scope = () => execFileSync(process.execPath, [script], { cwd: directory, env, encoding: 'utf8', stdio: 'pipe' }).trim();
  try {
    git('init', '-b', 'main');
    writeFileSync(join(directory, 'README.md'), 'guide\n');
    writeFileSync(join(directory, 'code.rs'), 'fn main() {}\n');
    git('add', '.');
    git('commit', '-m', 'base');
    assert.throws(scope);
    git('switch', '-c', 'docs');
    writeFileSync(join(directory, 'README.md'), 'updated guide\n');
    git('commit', '-am', 'docs');
    git('switch', 'main');
    git('merge', '--no-ff', 'docs', '-m', 'merge');
    assert.equal(scope(), 'full=false');
    env.GITHUB_EVENT_NAME = 'push';
    assert.equal(scope(), 'full=true');
    env.GITHUB_EVENT_NAME = 'pull_request';
    git('mv', '-f', 'code.rs', 'README.md');
    git('commit', '-am', 'rename');
    assert.equal(scope(), 'full=true');
  } finally { rmSync(directory, { recursive: true, force: true }); }
});

test('release scope CLI checks Git blobs, file modes and the merge base instead of the working tree', () => {
  const directory = mkdtempSync(join(tmpdir(), 'tdm-release-scope-'));
  const script = fileURLToPath(new URL('../validation-scope.mjs', import.meta.url));
  const env = { ...process.env, GITHUB_EVENT_NAME: 'pull_request',
    GIT_AUTHOR_NAME: 'Test', GIT_AUTHOR_EMAIL: 'test@example.com',
    GIT_COMMITTER_NAME: 'Test', GIT_COMMITTER_EMAIL: 'test@example.com' };
  const git = (...args) => execFileSync('git', args, { cwd: directory, env, stdio: 'pipe' });
  const scope = () => execFileSync(process.execPath, [script], { cwd: directory, env, encoding: 'utf8', stdio: 'pipe' }).trim();
  const write = version => {
    for (const [path, content] of Object.entries(releaseFiles(version))) writeFileSync(join(directory, path), content);
  };
  try {
    git('init', '-b', 'main');
    git('config', 'core.autocrlf', 'false');
    write('1.0.0');
    git('add', '.');
    git('commit', '-m', 'base');
    git('switch', '-c', 'release');
    write('1.1.0');
    git('commit', '-am', 'release');
    git('switch', 'main');
    git('merge', '--no-ff', 'release', '-m', 'merge');
    assert.equal(scope(), 'full=false');
    writeFileSync(join(directory, 'Cargo.lock'), 'uncommitted local changes\n');
    assert.equal(scope(), 'full=false');
    git('restore', 'Cargo.lock');
    env.GITHUB_EVENT_NAME = 'push';
    assert.equal(scope(), 'full=true');
    env.GITHUB_EVENT_NAME = 'pull_request';
    git('update-index', '--chmod=+x', 'Cargo.toml');
    git('commit', '--amend', '--no-edit');
    assert.equal(scope(), 'full=true');
  } finally { rmSync(directory, { recursive: true, force: true }); }
});

test('the Linux workflow completion gate rejects failed or unexpectedly skipped checks', { skip: process.platform === 'win32' }, () => {
  const workflow = readFileSync(new URL('../../workflows/validation.yml', import.meta.url), 'utf8');
  const script = workflow.split('  complete:\n')[1].split('        run: |\n')[1];
  const run = values => spawnSync('bash', ['-e', '-o', 'pipefail', '-c', script], {
    env: { ...process.env, GITHUB_STEP_SUMMARY: '/dev/null', ...values },
  }).status;
  for (const full of ['true', 'false']) {
    const expected = full === 'true' ? 'success' : 'skipped';
    const values = { SCOPE_RESULT: 'success', FULL: full, TEST_RESULT: expected, BROWSER_RESULT: expected, DOCKER_RESULT: expected, DASHBOARD_RESULT: expected, DESKTOP_RESULT: expected };
    assert.equal(run(values), 0);
    for (const name of ['SCOPE_RESULT', 'TEST_RESULT', 'BROWSER_RESULT', 'DOCKER_RESULT', 'DASHBOARD_RESULT', 'DESKTOP_RESULT']) {
      for (const result of ['success', 'skipped', 'failure', 'cancelled', '']) {
        if (result === values[name]) continue;
        assert.notEqual(run({ ...values, [name]: result }), 0, `${full}: ${name}=${result}`);
      }
    }
    assert.notEqual(run({ ...values, FULL: '' }), 0);
  }
});
